  handleEvent(event) {
    switch (event.type) {
      case "click": {
        // Prevent link being handled with link click handling.
        event.preventDefault();
        event.stopPropagation();

        const newEvent = new InAppNotificationEvent(
          "ctaclick",
          event,
          this.dataset.id
        );
        // Because we had to suppress the original event, send our own.
        this.dispatchEvent(newEvent);
        break;
      }
    }
  }
}

customElements.define("in-app-notification-button", InAppNotificationButton, {
  extends: "a",

  /**
   * Id of the notification this event was fired for.
   *
   * @type {string}
   */
  notificationId;

  /**
   *
   * @param {string} type - Event type.
   * @param {MouseEvent} event - Mouse event this is inheriting from.
   * @param {string} notificationId - ID of the notification this event is
   *   emitted for.
   */
  constructor(type, event, notificationId) {
    super(type, event);
    this.notificationId = notificationId;
  }
}

